# Count frequency of each column having 6s in the pattern region
test_grid_2d = []
for r in range(26):
    row = [1] * 12
    if r >= 17 and r < 23:
        row_str_lines = [
            [6, 1, 6, 1, 6, 6, 6, 6, 1, 1, 1, 1],   # row 17
            [1, 6, 6, 6, 6, 6, 6, 6, 1, 1, 1, 1],   # row 18
            [6, 6, 6, 6, 6, 6, 6, 1, 6, 1, 1, 1],   # row 19
            [6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 1, 1],   # row 20
            [6, 6, 6, 6, 6, 6, 6, 1, 1, 1, 1, 1],   # row 21
            [6, 6, 6, 6, 6, 6, 6, 6, 1, 1, 1, 1],   # row 22
        ]
        row = row_str_lines[r - 17]
    elif r == 23:
        row = [2] * 12

    test_grid_2d.append(row)

# For each column, count how many rows have 6
col_counts = {col: 0 for col in range(12)}
for col in range(12):
    for row_idx in range(26):
        if test_grid_2d[row_idx][col] == 6:
            col_counts[col] += 1

print("Column counts (how many rows have 6):")
for col in sorted(col_counts.keys()):
    print(f"  Col {col}: {col_counts[col]}")

# Also find the min/max column with any 6
columns_with_6 = set()
for col in range(12):
    for row_idx in range(26):
        if test_grid_2d[row_idx][col] == 6:
            columns_with_6.add(col)

print("\nColumns containing any 6:", sorted(columns_with_6))

