# Re-examine demo #1 carefully
demo_input_cols_with_7 = {}
for c in range(19):
    demo_input_cols_with_7[c] = []
    for r in range(12):
        val = 3
        if c == 18:
            val = 2  # Rightmost col always 2
        elif r == 0:
            if c == 17: val = 7
        elif r == 1:
            if c == 12 or c == 16: val = 7
        elif r == 2:
            if c == 12 or c == 15 or c == 16: val = 7
        elif r == 3:
            if 11 <= c <= 17: val = 7
        elif r == 4:
            if c == 13 or c == 17: val = 7
        elif r == 5:
            if c == 14 or c == 16: val = 7
        elif r == 6:
            if c == 16: val = 7

        if val == 7:
            demo_input_cols_with_7[c].append(r)

print("Columns containing 7 and their row indices:")
for c in sorted(demo_input_cols_with_7.keys()):
    print(f"  Col {c}: rows {demo_input_cols_with_7[c]}")

# The set of all columns with ANY 7
all_cols = [c for c in range(19) if demo_input_cols_with_7[c]]
print(f"\nAll columns with 7: {sorted(all_cols)}")
print(f"Min: {min(all_cols)}, Max: {max(all_cols)}")
print(f"Center = {min(all_cols)} + {len(all_cols)//2} = {min(all_cols) + len(all_cols)//2}")

